const invoice = $json.output;

const issues = [];

// Required field validation
if (!invoice.invoice_number) {
    issues.push("Missing invoice number");
}

if (!invoice.vendor_name) {
    issues.push("Missing vendor name");
}

if (!invoice.invoice_date) {
    issues.push("Missing invoice date");
}

if (!invoice.po_number) {
    issues.push("Missing PO number");
}

if (invoice.total_amount === undefined || invoice.total_amount === null) {
    issues.push("Missing total amount");
}

if (invoice.subtotal === undefined || invoice.subtotal === null) {
    issues.push("Missing subtotal");
}

if (invoice.tax === undefined || invoice.tax === null) {
    issues.push("Missing tax");
}

// Amount validation
const subtotal = Number(invoice.subtotal);
const tax = Number(invoice.tax);
const total = Number(invoice.total_amount);

if (
    !Number.isNaN(subtotal) &&
    !Number.isNaN(tax) &&
    !Number.isNaN(total)
) {
    const calculatedTotal = subtotal + tax;

    if (Math.abs(calculatedTotal - total) > 0.01) {
        issues.push(
            `Amount mismatch: subtotal + tax = ${calculatedTotal}, but invoice total = ${total}`
        );
    }
}

// Final validation status
const validationStatus = issues.length === 0
    ? "VALID"
    : "INVALID";

return [
    {
        json: {
            invoice_number: invoice.invoice_number || "",
            vendor_name: invoice.vendor_name || "",
            invoice_date: invoice.invoice_date || "",
            due_date: invoice.due_date || "",
            po_number: invoice.po_number || "",
            subtotal: subtotal,
            tax: tax,
            total_amount: total,
            currency: invoice.currency || "",
            validation_status: validationStatus,
            validation_issues: issues.join("; ")
        }
    }
];

const invoiceNumber = $('Invoice Data Validation').first().json.invoice_number;

// Get the result returned by Google Sheets
const sheetResult = $input.first().json;

// If Google Sheets returned an empty item,
// the invoice does not already exist.
const isDuplicate = Object.keys(sheetResult).length > 0;

return [
    {
        json: {
            invoice_number: invoiceNumber,
            is_duplicate: isDuplicate,
            duplicate_status: isDuplicate ? "DUPLICATE" : "NEW"
        }
    }
];

const invoice = $('Invoice Data Validation').first().json;
const po = $input.first().json;

const issues = [];

// Vendor validation
const invoiceVendor = invoice.vendor_name.trim().toLowerCase();
const poVendor = (po.Vendor_Name || "").trim().toLowerCase();

if (!poVendor) {
    issues.push("PO not found");
} else if (invoiceVendor !== poVendor) {
    issues.push(
        `Vendor mismatch: Invoice vendor is "${invoice.vendor_name}" but PO vendor is "${po.Vendor_Name}"`
    );
}

// PO amount validation
const invoiceAmount = Number(invoice.total_amount);
const poAmount = Number(po.PO_Amount);

if (!Number.isNaN(invoiceAmount) && !Number.isNaN(poAmount)) {
    if (Math.abs(invoiceAmount - poAmount) > 0.01) {
        issues.push(
            `Amount mismatch: Invoice total is ${invoiceAmount}, but PO amount is ${poAmount}`
        );
    }
}

// Currency validation
if (
    invoice.currency &&
    po.Currency &&
    invoice.currency.toUpperCase() !== po.Currency.toUpperCase()
) {
    issues.push(
        `Currency mismatch: Invoice currency is ${invoice.currency}, but PO currency is ${po.Currency}`
    );
}

const vendorMatch =
    poVendor !== "" && invoiceVendor === poVendor;

const amountMatch =
    !Number.isNaN(invoiceAmount) &&
    !Number.isNaN(poAmount) &&
    Math.abs(invoiceAmount - poAmount) <= 0.01;

const currencyMatch =
    invoice.currency &&
    po.Currency &&
    invoice.currency.toUpperCase() === po.Currency.toUpperCase();

const poMatchStatus =
    vendorMatch && amountMatch && currencyMatch
        ? "MATCHED"
        : "MISMATCH";

return [
    {
        json: {
            invoice_number: invoice.invoice_number,
            vendor_name: invoice.vendor_name,
            po_number: invoice.po_number,
            invoice_amount: invoiceAmount,
            po_amount: poAmount,
            invoice_currency: invoice.currency,
            po_currency: po.Currency,
            vendor_match: vendorMatch,
            amount_match: amountMatch,
            currency_match: currencyMatch,
            po_match_status: poMatchStatus,
            po_status: po.Status || "",
            po_validation_issues: issues.join("; ")
        }
    }
];

const invoice = $('Invoice Data Validation').first().json;
const duplicate = $('Duplicate Invoice Detection').first().json;
const po = $('PO & Vendor Validation').first().json;

let decision = "";
let reason = "";

// 1. Duplicate check
if (duplicate.is_duplicate === true) {
    decision = "REJECTED";
    reason = "Duplicate invoice detected.";
}

// 2. Invoice validation
else if (invoice.validation_status !== "VALID") {
    decision = "HUMAN REVIEW";
    reason = invoice.validation_issues || "Invoice validation failed.";
}

// 3. PO matching
else if (po.po_match_status !== "MATCHED") {
    decision = "HUMAN REVIEW";
    reason = po.po_validation_issues || "PO matching failed.";
}

// 4. PO status
else if (po.po_status !== "Approved") {
    decision = "HUMAN REVIEW";
    reason = `PO status is "${po.po_status}", which requires review.`;
}

// 5. All checks passed
else {
    decision = "APPROVED";
    reason = "Invoice passed validation, duplicate check, vendor matching, amount matching, currency matching, and PO approval checks.";
}

return [
    {
        json: {
            invoice_number: invoice.invoice_number,
            vendor_name: invoice.vendor_name,
            invoice_date: invoice.invoice_date,
            due_date: invoice.due_date,
            po_number: invoice.po_number,
            subtotal: invoice.subtotal,
            tax: invoice.tax,
            total_amount: invoice.total_amount,
            currency: invoice.currency,

            validation_status: invoice.validation_status,
            validation_issues: invoice.validation_issues,

            duplicate_status: duplicate.duplicate_status,

            po_match_status: po.po_match_status,
            vendor_match: po.vendor_match,
            amount_match: po.amount_match,
            currency_match: po.currency_match,
            po_status: po.po_status,

            decision: decision,
            reason: reason,

            processed_date: new Date().toISOString()
        }
    }
];

